import{c as t,Q as a,j as r,m as l}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Claude 5 三模型 Harness 稽核合成報告（Fable 5 / Opus 5 / Sonnet 5）","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-31-claude5-tri-model-harness-audit.md","filePath":"research/reports/2026-07-31-claude5-tri-model-harness-audit.md","lastUpdated":1785909234000}'),o={name:"research/reports/2026-07-31-claude5-tri-model-harness-audit.md"};function s(i,e,d,n,c,u){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="claude-5-三模型-harness-稽核合成報告-fable-5-opus-5-sonnet-5" tabindex="-1">Claude 5 三模型 Harness 稽核合成報告（Fable 5 / Opus 5 / Sonnet 5） <a class="header-anchor" href="#claude-5-三模型-harness-稽核合成報告-fable-5-opus-5-sonnet-5" aria-label="Permalink to &quot;Claude 5 三模型 Harness 稽核合成報告（Fable 5 / Opus 5 / Sonnet 5）&quot;">​</a></h1><blockquote><p>目的：驗證 2026-07-31 三輪修正（停用兩支零真陽性 advisory hook、byte 門檻回錨 20,400/23,000、core.md OBSERVE/PROPOSE 程序句刪除、97 污染格刪除）是否符合 Claude 5 系列模型設計——能力最大化、效率、成本與 system prompt 最小化。 方法：三個 fresh-context sub-agent 分別綁 claude-fable-5 / claude-opus-5 / claude-sonnet-5，唯讀全 repo，各自親跑確定性量測。parent 對帳：Opus 回報之 19,858 bytes / measure GATE PASS / healthcheck 248-0-0 與 parent 親跑一致。 標籤：判斷部分 = assisted_verified_success（確定性數字已對帳；判斷無確定性 oracle）。</p></blockquote><h2 id="_1-四項修正三方判定矩陣" tabindex="-1">1. 四項修正三方判定矩陣 <a class="header-anchor" href="#_1-四項修正三方判定矩陣" aria-label="Permalink to &quot;1. 四項修正三方判定矩陣&quot;">​</a></h2><table tabindex="0"><thead><tr><th>修正</th><th>Fable 5</th><th>Opus 5</th><th>Sonnet 5</th></tr></thead><tbody><tr><td>① 停用 blindspot-domain-lint / loop-charter-gate</td><td>符合（推理預算調解稅移除，乘法級）</td><td>正確，本輪最有價值</td><td>恰當，非誤傷（本就恆 exit 0）</td></tr><tr><td>② byte 門檻回錨 20,400/23,000</td><td>符合，方向正確</td><td>正確；「餘裕=預先授權成長」是反 Goodhart 設計</td><td>方向正確，PROVISIONAL 應視為未定案</td></tr><tr><td>③ OBSERVE/PROPOSE 兩句刪除</td><td>符合，取捨精準</td><td>正確但低收益；regress 是絆線非行為 eval</td><td><strong>PROPOSE 句可、OBSERVE 句對 quality 檔位偏深，建議回補</strong></td></tr><tr><td>④ 97 污染格刪除</td><td>符合（壞 oracle 直接應用）</td><td>正確；實質是保護閘門非剪枝（假結論曾指向錯誤剪枝方向）</td><td>符合，收據齊</td></tr></tbody></table><p><strong>唯一分歧</strong>：OBSERVE「讀 exports + caller + utility」句。Sonnet 5 指出 context-engineering-claude5.md §3.5 檔位警示——「無退化」實證只涵蓋 advanced 檔位，quality 檔位執行 sub-agent 任務時具體枚舉「讀什麼」仍有價值；Fable/Opus 判定已內化。2:1 維持刪除，rollback_signal 已上膛（範圍遺漏型失誤重現 ≥2 次即回補）；Sonnet 給的精簡回補寫法留存於本檔供觸發時使用：「改動前讀 exports + 直接 caller + 共用 utility；不清楚現有設計為何如此，先問再動」。</p><h2 id="_2-閘門強度-三方一致零誤傷" tabindex="-1">2. 閘門強度：三方一致零誤傷 <a class="header-anchor" href="#_2-閘門強度-三方一致零誤傷" aria-label="Permalink to &quot;2. 閘門強度：三方一致零誤傷&quot;">​</a></h2><p>hard-block 類（block-dangerous / protect-sensitive-files / test-integrity-guard / test-file-redflag / pre-commit-review / gate-widening-guard / branch-isolation-guard）全數在掛、exit 2 路徑完好；§TEST 條文三輪剪枝一字未動；byte gate 反向收緊。唯一降級 = clause 4e7858ae <code>[E]</code>→<code>[E*]</code>，已登記缺口與回掛條件，非靜默消失。</p><h2 id="_3-三方共同結論-下一輪主戰場不在-rules" tabindex="-1">3. 三方共同結論：下一輪主戰場不在 rules <a class="header-anchor" href="#_3-三方共同結論-下一輪主戰場不在-rules" aria-label="Permalink to &quot;3. 三方共同結論：下一輪主戰場不在 rules&quot;">​</a></h2><ul><li>rules 側 19,858 bytes、餘裕 542（2.7%），剩餘 <code>[P]</code> 候選合計僅 ~400 B——不值得單獨開輪，當「淨零增長」的抵扣額度即可（Opus 已逐條列出候選：/rewind 計數句、既有慣例與 output-discipline 同源重複、G1 教學句、compact delta hint 句、迷失例句、L5 整節）。</li><li><strong>skills/agents description 實測 18,543 bytes ≈ rules 等量的第二座稅，卻無 byte gate</strong>（skill-roster-audit 的 never-triggers 判準因 telemetry 稀疏停用）。pilot / multi-mode-skill / quality-pipeline 的 trigger 同義詞枚舉屬過度枚舉（規則 2：表達力強的 interface 勝過窮舉）。</li><li><strong>CLAUDE.md 雙重注入</strong>（global 鏡像 + project，逐字相同 ~1.4k B/回合）違反規則 4 去重複；且注入快照可能落後 repo（剪枝 repo 生效、注入層失效的靜默漂移風險）。建議 global 側改空指針並確認快照更新機制。</li><li>量測口徑應擴至「實際注入總量」（rules + CLAUDE.md×注入次數 + descriptions + hook 注入 ≈ 43.2k bytes），目前 gate 只治理一半。</li></ul><h2 id="_4-待裁決事項-人閘" tabindex="-1">4. 待裁決事項（人閘） <a class="header-anchor" href="#_4-待裁決事項-人閘" aria-label="Permalink to &quot;4. 待裁決事項（人閘）&quot;">​</a></h2><ol><li><code>verification-waiver-gate.sh</code>：證據基礎已撤回（剩 pilot B11 n=2），Fable/Opus 皆點名依同判準應入下輪停用候選（30 天窗與本輪兩支同步覆審）。</li><li><code>taste-reference-lint.sh</code> 路徑錯配：掛 PreToolUse[Agent|Workflow] 但目標行為在使用者直接請求路徑——名實落差比被停用的兩支更大，且有明確修法（加掛 UserPromptSubmit）。</li><li>Opus 建議把 advisory hook 治理定為節拍：「advisory 預設 30 天觀察期，期滿無真實觸發自動退役 retired/」——把一次性人工裁決制度化。</li><li><code>loop.md §L5</code> 自認無補 Body 路徑，依 Framework Integrity 已達可剪門檻——留文件價值或剪，需裁決。</li><li>回掛條件的觀察者問題（Opus）：hook 停用後不再有觸發紀錄，「本應被攔的失誤」需獨立觀察者（如 LESSONS 記錄觸發回掛檢視）。</li><li>Sonnet 的 OBSERVE 回補提案（見 §1）。</li></ol><h2 id="_5-結構性摩擦-三方各報一個" tabindex="-1">5. 結構性摩擦（三方各報一個） <a class="header-anchor" href="#_5-結構性摩擦-三方各報一個" aria-label="Permalink to &quot;5. 結構性摩擦（三方各報一個）&quot;">​</a></h2><ul><li><strong>Fable 5</strong>：CLAUDE.md 雙重注入 + 注入快照過期（見 §3）。</li><li><strong>Opus 5</strong>：委派拓撲與驗證拓撲不同構——graph.md 鼓勵稽核外派，core.md §TEST 要求裁定收回 parent 親跑；對「產出即判斷」的稽核任務，sub-agent 結構上只能交付 assisted_verified_success。此為 loop.md §L1 verifier 分離缺口的鏡像。</li><li><strong>Sonnet 5</strong>：gate-widening-guard 對唯讀 diff 操作的 lexical 假陽性（shell 重定向被當寫入動詞）——與 waiver-gate 同族的 lexical 上限問題。</li></ul>',13)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
